type C struct {
}

func (o *C) run() int {
  sum := 0
  i := 0
  for i < 10 {
    i = i + 1
    if i == 3 {
      continue
    }
    if i == 6 {
      break
    }
    sum = sum + i
  }
  j := 0
  for {
    sum = sum + 10
    j = j + 1
    if !(j < 3) {
      break
    }
  }
  switch j {
  case 3:
    sum = sum + 100
  default:
    sum = sum + 1
  }
  return sum
}
